import csv
import os
from decimal import Decimal, getcontext

getcontext().prec = 1000


def main():
    groups = {}
    path = os.path.join("дані", "виміри.csv")
    with open(path, encoding="utf-8-sig", newline="") as f:
        reader = csv.reader(f)
        next(reader, None)
        for row in reader:
            if not row:
                continue
            name = row[0].strip()
            groups.setdefault(name, [])
            if len(row) > 1:
                v = row[1].strip()
                if v != "":
                    groups[name].append(Decimal(v))

    out = []
    for name in sorted(groups):
        vals = sorted(groups[name])
        n = len(vals)
        if n == 0:
            out.append(f"{name}: —")
            continue
        if n % 2:
            m = vals[n // 2]
        else:
            m = (vals[n // 2 - 1] + vals[n // 2]) / 2
        if m == 0:
            s = "0"
        else:
            s = format(m.normalize(), "f")
        out.append(f"{name}: {s}")
    print("\n".join(out))


main()

